import { useState } from "react";
import { useNavigate } from "react-router-dom"; 
import "./styles/AdminUsers.css";

function AdminUsers({ users, user, onViewInfo, onLogout, onBack }) {
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editingUser, setEditingUser] = useState(null);
  const [usersList, setUsersList] = useState(users || []);
  const navigate = useNavigate();

  const handleEditClick = (userData) => {
    setEditingUser({ ...userData });
    setShowEditModal(true);
  };

  const handleAddUser = () => {
    setEditingUser({ name: "", username: "", role: "", email: "" });
    setShowEditModal(true);
  };

  const handleCloseModal = () => {
    setShowEditModal(false);
    setEditingUser(null);
  };

  const handleSaveUser = (e) => {
    e.preventDefault();
    if (!editingUser.username) {
      // Generar username único simple si está vacío
      const newUser = { ...editingUser, username: `user${Date.now()}` };
      setUsersList([...usersList, newUser]);
    } else {
      setUsersList(usersList.map(u => u.username === editingUser.username ? editingUser : u));
    }
    handleCloseModal();
  };

  const handleDeleteUser = (username) => {
    setUsersList(usersList.filter(u => u.username !== username));
  };

  const handleLogoutAndGoBack = () => {
    if (onLogout) onLogout();
    navigate("/adminB"); 
  };

  return (
    <div className="admin-container">
      <header className="admin-header">
        <div className="header-left">
          {onBack && (
            <button className="back-btn" onClick={onBack} title="Volver">←</button>
          )}
          <h1 className="header-title">Usuarios</h1>
        </div>
        <div className="header-right">
          <div className="user-menu-wrapper">
            <button className="user-btn" onClick={() => setShowUserMenu(!showUserMenu)}>
              <span className="user-icon">
                <i className="bi bi-person-circle"></i>
              </span>
              <span className="user-name">{user.username}</span>
            </button>
            {showUserMenu && (
              <div className="user-dropdown">
                <button
                  className="dropdown-item"
                  onClick={() => { onViewInfo(); setShowUserMenu(false); }}
                >
                  Ver información
                </button>
                <button
                  className="dropdown-item logout"
                  onClick={handleLogoutAndGoBack}
                >
                  Cerrar sesión
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

<main className="admin-main">
  <div className="users-section">
    <div className="section-header">
      <h2>Gestión de Usuarios</h2>
    </div>

    <table className="users-table">
      <thead>
        <tr>
          <th>Nombre</th>
          <th>Usuario</th>
          <th>Rol</th>
          <th>Email</th>
          <th>Opciones</th>
        </tr>
      </thead>
      <tbody>
        {usersList.map(userData => (
          <tr key={userData.username}>
            <td>{userData.name}</td>
            <td>{userData.username}</td>
            <td>{userData.role}</td>
            <td>{userData.email}</td>
            <td className="options-cell">
              <button className="option-btn edit" onClick={() => handleEditClick(userData)} title="Editar">
                <i className="bi bi-pencil-fill"></i>
              </button>
              <button className="option-btn delete" onClick={() => handleDeleteUser(userData.username)} title="Eliminar">
                <i className="bi bi-trash-fill"></i>
              </button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>

    <div className="add-user-container" style={{ marginTop: "20px", textAlign: "center" }}>
      <button className="add-user-btn" onClick={handleAddUser}>+ Agregar nuevo usuario</button>
    </div>
  </div>
</main>


      {showEditModal && editingUser && (
        <div className="modal-overlay" onClick={handleCloseModal}>
          <div className="modal-content users-section" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>{editingUser.username ? "Editar Usuario" : "Agregar Usuario"}</h2>
              <button className="modal-close" onClick={handleCloseModal}>✕</button>
            </div>
            <div className="modal-body">
              <form className="edit-form" onSubmit={handleSaveUser}>
                <div className="form-group">
                  <label>Nombre:</label>
                  <input type="text" value={editingUser.name} onChange={e => setEditingUser({...editingUser, name: e.target.value})} placeholder="Nombre completo"/>
                </div>
                <div className="form-group">
                  <label>Usuario:</label>
                  <input type="text" value={editingUser.username} onChange={e => setEditingUser({...editingUser, username: e.target.value})} placeholder="Usuario" disabled={editingUser.username !== ""}/>
                </div>
                <div className="form-group">
                  <label>Rol:</label>
                  <input type="text" value={editingUser.role} onChange={e => setEditingUser({...editingUser, role: e.target.value})} placeholder="Rol del usuario"/>
                </div>
                <div className="form-group">
                  <label>Email:</label>
                  <input type="email" value={editingUser.email} onChange={e => setEditingUser({...editingUser, email: e.target.value})} placeholder="Email"/>
                </div>
                <div className="form-actions">
                  <button type="button" className="btn-cancel" onClick={handleCloseModal}>Cancelar</button>
                  <button type="submit" className="btn-save">Guardar</button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default AdminUsers;
